insert into research.ecclesiastical_import_rows (
  batch_id,
  source_record_key,
  entity_scope,
  raw_name,
  canonical_type,
  country_code,
  latitude,
  longitude,
  payload,
  validation_errors,
  status
)
select
  batches.id,
  source_data.qid,
  'jurisdiction',
  source_data.name,
  source_data.canonical_type,
  source_data.country_code,
  source_data.latitude,
  source_data.longitude,
  to_jsonb(source_data),
  '{}'::text[],
  'validated'
from source_data
join research.batches
  on batches.slug = 'ecclesiastical-' || source_data.continent || '-01'
on conflict (batch_id, source_record_key) do update
set
  raw_name = excluded.raw_name,
  canonical_type = excluded.canonical_type,
  country_code = excluded.country_code,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  payload = excluded.payload,
  validation_errors = excluded.validation_errors,
  status = case
    when research.ecclesiastical_import_rows.status = 'promoted'
      then 'promoted'
    else excluded.status
  end,
  updated_at = now();

with import_rows as (
  select
    import_row.payload,
    coalesce(
      (
        select id
        from public.ecclesiastical_sources
        where url = nullif(import_row.payload->>'verification_url', '')
      ),
      (
        select id
        from public.ecclesiastical_sources
        where url = 'https://query.wikidata.org/sparql'
      )
    ) as jurisdiction_source_id
  from research.ecclesiastical_import_rows as import_row
  join research.batches as batch
    on batch.id = import_row.batch_id
  where batch.dataset = 'ecclesiastical_jurisdictions'
    and import_row.payload ? 'qid'
)
insert into public.ecclesiastical_jurisdictions as jurisdiction (
  slug,
  name,
  canonical_type,
  tradition,
  country_code,
  status,
  erected_year,
  description,
  official_url,
  primary_source_id,
  is_published
)
select
  coalesce(
    nullif(import_rows.payload->>'existing_jurisdiction_slug', ''),
    'jurisdiction-wikidata-' || lower(import_rows.payload->>'qid')
  ),
  import_rows.payload->>'name',
  import_rows.payload->>'canonical_type',
  import_rows.payload->>'tradition',
  import_rows.payload->>'country_code',
  'active',
  (import_rows.payload->>'erected_year')::integer,
  case
    when import_rows.payload->>'tradition' = 'eastern'
      then 'Circunscrição arquiepiscopal de uma Igreja Católica oriental.'
    else 'Circunscrição arquiepiscopal da Igreja Católica de tradição latina.'
  end,
  nullif(import_rows.payload->>'official_url', ''),
  import_rows.jurisdiction_source_id,
  true
from import_rows
on conflict (slug) do update
set
  name = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.name
    else jurisdiction.name
  end,
  canonical_type = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.canonical_type
    else jurisdiction.canonical_type
  end,
  tradition = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.tradition
    else jurisdiction.tradition
  end,
  country_code = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.country_code
    else jurisdiction.country_code
  end,
  erected_year = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.erected_year
    else jurisdiction.erected_year
  end,
  description = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.description
    else jurisdiction.description
  end,
  official_url = coalesce(jurisdiction.official_url, excluded.official_url),
  primary_source_id = case
    when jurisdiction.slug like 'jurisdiction-wikidata-%'
      then excluded.primary_source_id
    else jurisdiction.primary_source_id
  end,
  is_published = true,
  updated_at = now();

with promoted as (
  select
    jurisdiction.id as jurisdiction_id,
    import_row.payload,
    (
      select id
      from public.ecclesiastical_sources
      where url = 'https://query.wikidata.org/sparql'
    ) as geodata_source_id
  from research.ecclesiastical_import_rows as import_row
  join research.batches as batch
    on batch.id = import_row.batch_id
  join public.ecclesiastical_jurisdictions as jurisdiction
    on jurisdiction.slug = coalesce(
      nullif(import_row.payload->>'existing_jurisdiction_slug', ''),
      'jurisdiction-wikidata-' || lower(import_row.payload->>'qid')
    )
  where batch.dataset = 'ecclesiastical_jurisdictions'
    and import_row.payload ? 'qid'
),
identifiers as (
  select
    promoted.jurisdiction_id,
    identifier.namespace,
    identifier.external_id,
    promoted.geodata_source_id
  from promoted
  cross join lateral (
    values
      ('wikidata', promoted.payload->>'qid'),
      ('catholic_hierarchy', promoted.payload->>'catholic_hierarchy_id'),
      ('gcatholic', promoted.payload->>'gcatholic_id')
  ) as identifier(namespace, external_id)
  where nullif(identifier.external_id, '') is not null
)
insert into research.ecclesiastical_jurisdiction_identifiers (
  jurisdiction_id,
  namespace,
  external_id,
  source_id
)
select jurisdiction_id, namespace, external_id, geodata_source_id
from identifiers
on conflict (namespace, external_id) do update
set
  jurisdiction_id = excluded.jurisdiction_id,
  source_id = excluded.source_id;

with promoted as (
  select
    jurisdiction.id as jurisdiction_id,
    import_row.payload,
    (
      select id
      from public.ecclesiastical_sources
      where url = 'https://query.wikidata.org/sparql'
    ) as geodata_source_id
  from research.ecclesiastical_import_rows as import_row
  join research.batches as batch
    on batch.id = import_row.batch_id
  join public.ecclesiastical_jurisdictions as jurisdiction
    on jurisdiction.slug = coalesce(
      nullif(import_row.payload->>'existing_jurisdiction_slug', ''),
      'jurisdiction-wikidata-' || lower(import_row.payload->>'qid')
    )
  where batch.dataset = 'ecclesiastical_jurisdictions'
    and import_row.payload ? 'qid'
)
insert into public.ecclesiastical_sites as site (
  jurisdiction_id,
  slug,
  name,
  site_type,
  country_code,
  location,
  min_zoom,
  display_rank,
  valid_from_year,
  official_url,
  location_accuracy,
  primary_source_id,
  is_primary,
  is_published
)
select
  promoted.jurisdiction_id,
  coalesce(
    nullif(promoted.payload->>'existing_site_slug', ''),
    'apostolic-see-wikidata-' || lower(promoted.payload->>'qid')
  ),
  'Sede da ' || (promoted.payload->>'name'),
  'apostolic_see',
  promoted.payload->>'country_code',
  extensions.st_point(
    (promoted.payload->>'longitude')::double precision,
    (promoted.payload->>'latitude')::double precision
  )::extensions.geography,
  case
    when promoted.payload->>'canonical_type' in (
      'metropolitan_archdiocese',
      'metropolitan_archeparchy'
    ) then 3.2
    else 4.4
  end,
  case
    when promoted.payload->>'canonical_type' in (
      'metropolitan_archdiocese',
      'metropolitan_archeparchy'
    ) then 10
    else 15
  end,
  (promoted.payload->>'erected_year')::integer,
  nullif(promoted.payload->>'official_url', ''),
  'approximate',
  promoted.geodata_source_id,
  true,
  true
from promoted
on conflict (slug) do update
set
  jurisdiction_id = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.jurisdiction_id
    else site.jurisdiction_id
  end,
  name = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.name
    else site.name
  end,
  country_code = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.country_code
    else site.country_code
  end,
  location = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.location
    else site.location
  end,
  min_zoom = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.min_zoom
    else site.min_zoom
  end,
  display_rank = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.display_rank
    else site.display_rank
  end,
  valid_from_year = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.valid_from_year
    else site.valid_from_year
  end,
  official_url = coalesce(site.official_url, excluded.official_url),
  location_accuracy = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.location_accuracy
    else site.location_accuracy
  end,
  primary_source_id = case
    when site.slug like 'apostolic-see-wikidata-%'
      then excluded.primary_source_id
    else site.primary_source_id
  end,
  is_primary = true,
  is_published = true,
  updated_at = now();

update research.ecclesiastical_import_rows as import_row
set
  promoted_jurisdiction_id = jurisdiction.id,
  promoted_site_id = site.id,
  status = 'promoted',
  updated_at = now()
from research.batches as batch,
     public.ecclesiastical_jurisdictions as jurisdiction,
     public.ecclesiastical_sites as site
where batch.id = import_row.batch_id
  and batch.dataset = 'ecclesiastical_jurisdictions'
  and import_row.payload ? 'qid'
  and jurisdiction.slug = coalesce(
    nullif(import_row.payload->>'existing_jurisdiction_slug', ''),
    'jurisdiction-wikidata-' || lower(import_row.payload->>'qid')
  )
  and site.slug = coalesce(
    nullif(import_row.payload->>'existing_site_slug', ''),
    'apostolic-see-wikidata-' || lower(import_row.payload->>'qid')
  );

update research.batches
set
  status = case when status = 'planned' then 'in_progress' else status end,
  started_at = coalesce(started_at, now()),
  updated_at = now()
where dataset = 'ecclesiastical_jurisdictions'
  and slug in (
    'ecclesiastical-africa-01',
    'ecclesiastical-americas-01',
    'ecclesiastical-asia-01',
    'ecclesiastical-europe-01',
    'ecclesiastical-oceania-01'
  );

comment on table research.ecclesiastical_jurisdiction_identifiers is
  'Identificadores externos usados para deduplicar circunscrições e preservar a rastreabilidade entre fontes.';
